<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:11px}h1{margin:0;font-size:22px}.header{border-bottom:2px solid #0f766e;padding-bottom:14px;margin-bottom:18px}.cards{width:100%;margin-bottom:18px}.cards td{background:#f1f5f9;padding:10px;width:25%}.label{font-size:9px;text-transform:uppercase;color:#64748b}.value{font-size:18px;font-weight:bold;margin-top:4px}table{width:100%;border-collapse:collapse}th{background:#0f766e;color:white;text-align:left}th,td{border:1px solid #d0d5dd;padding:7px}.section{margin:16px 0 7px;font-weight:bold;font-size:14px}</style></head><body><div class="header"><h1>Logistics Performance Report</h1><div style="color:#667085">Generated {{ now()->format('M d, Y H:i') }}</div></div><table class="cards"><tr><td><div class="label">Total orders</div><div class="value">{{ $analytics['summary']['total_orders'] }}</div></td><td><div class="label">Delivered</div><div class="value">{{ $analytics['summary']['delivery_rate'] }}%</div></td><td><div class="label">Sorting breaches</div><div class="value">{{ $analytics['summary']['sorting_breaches'] }}</div></td><td><div class="label">Final-mile breaches</div><div class="value">{{ $analytics['summary']['final_mile_breaches'] }}</div></td></tr></table><div class="section">Daily volume</div><table><thead><tr><th>Date</th><th>Volume</th><th>Delivered</th></tr></thead><tbody>@foreach($analytics['daily_volume'] as $day)<tr><td>{{ $day['date'] }}</td><td>{{ $day['volume'] }}</td><td>{{ $day['delivered'] }}</td></tr>@endforeach</tbody></table><div class="section">SLA breaches</div><table><thead><tr><th>AWB</th><th>Sorting hours</th><th>Final-mile hours</th><th>Classification</th></tr></thead><tbody>@foreach($analytics['sla_breaches'] as $breach)<tr><td>{{ $breach['awb_number'] }}</td><td>{{ $breach['sorting_hours'] ?? '—' }}</td><td>{{ $breach['final_mile_hours'] ?? '—' }}</td><td>{{ $breach['status'] }}</td></tr>@endforeach</tbody></table><